24	+
25	+use crate::error::GraphError;
26	+
27	+const COMMIT_MARK: char = '\u{1}';
28	+
29	+/// Changeset file name to the number of the pull request that added it. One `git log`, however many changesets there
30	+/// are. A changeset whose commit subject names no pull request is left out.
31	+pub fn changeset_pull_requests(
32	+    git: &GitAccess<'_>,
33	+    changesets_dir: &Path,
34	+) -> Result<BTreeMap<String, u64>, GraphError> {
35	+    let dir = changesets_dir.to_string_lossy();
36	+    let args = [
37	+        "log",
38	+        "--first-parent",
39	+        "-m",
40	+        "--diff-filter=A",
41	+        "--name-only",
42	+        "--format=%x01%s",
43	+        "--",
44	+        dir.as_ref(),
45	+    ];
46	+    let output = git.runner().run("git", &args, git.root()).map_err(VcsError::from)?;
47	+    // A repository with no commit has no history to read; every other failure stays an error.
48	+    if !output.success() && output.stderr.contains("does not have any commits yet") {
49	+        return Ok(BTreeMap::new());
50	+    }
51	+    if !output.success() {
52	+        return Err(VcsError::Git(format!(
53	+            "`git log` failed in `{}`: {}",
54	+            git.root().display(),
55	+            output.redacted_stderr()
56	+        ))
57	+        .into());
58	+    }
59	+    Ok(parse_changeset_prs(&output.stdout))
60	+}
61	+
62	+/// The pull request number in a commit subject: `Merge pull request #12 from ...` or `Title (#12)`.
63	+fn pull_request_of(subject: &str) -> Option<u64> {
64	+    if let Some(rest) = subject.strip_prefix("Merge pull request #") {
65	+        return rest.split_whitespace().next()?.parse().ok();
66	+    }
67	+    let tail = subject.trim_end().strip_suffix(')')?;
68	+    tail.rsplit_once("(#")?.1.parse().ok()
69	+}
70	+
71	+fn parse_changeset_prs(log: &str) -> BTreeMap<String, u64> {
72	+    let mut found = BTreeMap::new();
73	+    for block in log.split(COMMIT_MARK).skip(1) {
74	+        let mut lines = block.lines();
75	+        let Some(pr) = lines.next().and_then(pull_request_of) else {
76	+            continue;
77	+        };
78	+        for path in lines.filter(|line| !line.is_empty()) {
79	+            // A changeset is known by its id, the file name without `.md`. The log is newest first and a released
80	+            // changeset's name can be reused, so the first addition seen is the file that exists now.
81	+            if let Some(id) = Path::new(path).file_stem().and_then(|stem| stem.to_str()) {
82	+                found.entry(id.to_owned()).or_insert(pr);
83	+            }
84	+        }
85	+    }
86	+    found
87	+}
